package dev.stillday.app

import android.content.Context
import androidx.test.core.app.ApplicationProvider
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import dev.stillday.app.updates.*
import dev.stillday.domain.*
import kotlinx.coroutines.*
import kotlinx.coroutines.flow.first
import kotlinx.serialization.encodeToString
import org.junit.Assert.*
import org.junit.Assume.assumeTrue
import org.junit.Test
import org.junit.runner.RunWith
import java.io.File
import java.security.MessageDigest

/** Assets are generated by scripts/prepare-update-tests.py, never checked into source control. */
@RunWith(AndroidJUnit4::class)
class UpdaterTest {
    private val app get() = ApplicationProvider.getApplicationContext<StilldayApplication>()
    private val assets get() = InstrumentationRegistry.getInstrumentation().context.assets
    private fun manifest(): UpdateManifest {
        assumeTrue("Run scripts/prepare-update-tests.py for real APK integration tests", assets.list("updates").orEmpty().contains("manifest.json"))
        return UpdatePolicy.json.decodeFromString(assets.open("updates/manifest.json").bufferedReader().use { it.readText() })
    }
    private fun asset(name: String, directory: File): File = File(directory, name).also { file -> assets.open("updates/$name").use { input -> file.outputStream().use { input.copyTo(it) } } }
    private fun update(m: UpdateManifest) = AppUpdate(m, "https://github.com/${UpdatePolicy.REPOSITORY}/releases/download/test/Stillday.apk", UpdatePolicy.RELEASES_URL)
    private fun temp(): File = File(app.cacheDir, "update-test-${newId()}").apply { mkdirs() }

    @Test fun actualApkVerificationRejectsWrongKeyTruncationAndVersion() {
        val m = manifest()
        val directory = temp()
        try {
            val good = asset("good.apk", directory)
            val verifier = ApkVerifier(app)
            verifier.verify(good, update(m))
            val bad = asset("wrong-key.apk", directory)
            val wrongDigest = MessageDigest.getInstance("SHA-256").digest(bad.readBytes()).hex()
            try { verifier.verify(bad, update(m.copy(sizeBytes = bad.length(), sha256 = wrongDigest))); fail("Wrong key accepted") }
            catch (e: IllegalArgumentException) { assertTrue(e.message.orEmpty().contains("signing key")) }
            val short = File(directory, "short.apk").apply { val bytes = ByteArray(100); good.inputStream().use { it.read(bytes) }; writeBytes(bytes) }
            try { verifier.verify(short, update(m)); fail("Partial download accepted") } catch (_: IllegalArgumentException) { }
            try { verifier.verify(good, update(m.copy(versionCode = m.versionCode + 1))); fail("Incorrect version accepted") } catch (_: IllegalArgumentException) { }
        } finally { directory.deleteRecursively() }
    }

    private class FixtureTransport(val m: UpdateManifest, val apk: File, val stall: Boolean = false, val corrupt: Boolean = false) : UpdateTransport {
        var checks = 0
        var offline = false
        override suspend fun text(url: String, maxBytes: Int): String {
            if (offline) throw java.io.IOException("Connection unavailable")
            if (url == UpdatePolicy.API_URL) {
                checks++
                return """{"tag_name":"v-test","assets":[{"name":"update.json","browser_download_url":"https://github.com/${UpdatePolicy.REPOSITORY}/releases/download/test/update.json"},{"name":"Stillday.apk","size":${m.sizeBytes},"browser_download_url":"https://github.com/${UpdatePolicy.REPOSITORY}/releases/download/test/Stillday.apk"}]}"""
            }
            return UpdatePolicy.json.encodeToString(m)
        }
        override suspend fun download(url: String, destination: File, expectedBytes: Long, progress: (Long) -> Unit) {
            if (stall) { destination.writeBytes(byteArrayOf(1)); progress(1); awaitCancellation() }
            if (corrupt) destination.writeBytes(ByteArray(expectedBytes.toInt())) else apk.copyTo(destination, overwrite = true)
            progress(destination.length())
        }
    }

    @Test fun verifiedDownloadSurvivesManagerRecreationAndChecksAreThrottled() = runBlocking {
        val m = manifest(); val directory = temp(); val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
        val preferences = "updater-test-${newId()}"
        try {
            val transport = FixtureTransport(m, asset("good.apk", directory))
            val manager = UpdateManager(app, transport, scope = scope, preferencesName = preferences, directory = directory)
            manager.check(force = true)
            assertEquals(UpdatePhase.AVAILABLE, manager.state.value.phase)
            manager.check(); assertEquals(1, transport.checks)
            manager.download()
            withTimeout(15_000) { manager.state.first { it.phase == UpdatePhase.READY || it.phase == UpdatePhase.ERROR } }
            assertEquals(UpdatePhase.READY, manager.state.value.phase)
            val restored = UpdateManager(app, transport, scope = scope, preferencesName = preferences, directory = directory)
            assertEquals(UpdatePhase.READY, restored.state.value.phase)
            assertEquals(m, restored.state.value.update?.manifest)
            transport.offline = true
            restored.check(force = true)
            assertEquals(UpdatePhase.READY, restored.state.value.phase)
            assertEquals(m, restored.state.value.update?.manifest)
        } finally { scope.cancel(); directory.deleteRecursively(); app.deleteSharedPreferences(preferences) }
    }

    @Test fun cancellingDownloadRemovesPartialFilesAndKeepsRecords() = runBlocking {
        val m = manifest(); val directory = temp(); val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
        val preferences = "updater-test-${newId()}"
        app.repository.initialize(); val before = app.repository.state.value.data
        try {
            val manager = UpdateManager(app, FixtureTransport(m, asset("good.apk", directory), stall = true), scope = scope, preferencesName = preferences, directory = directory)
            manager.check(force = true); manager.download()
            withTimeout(5000) { manager.state.first { it.downloadedBytes > 0 } }
            manager.cancelDownload()
            withTimeout(5000) { manager.state.first { it.phase == UpdatePhase.AVAILABLE } }
            assertFalse(File(directory, "download.part").exists())
            assertFalse(File(directory, "update.apk").exists())
            assertEquals(before, app.repository.state.value.data)
        } finally { scope.cancel(); directory.deleteRecursively(); app.deleteSharedPreferences(preferences) }
    }

    @Test fun corruptDownloadIsNeverOfferedForInstallation() = runBlocking {
        val m = manifest(); val directory = temp(); val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
        val preferences = "updater-test-${newId()}"
        try {
            val manager = UpdateManager(app, FixtureTransport(m, asset("good.apk", directory), corrupt = true), scope = scope, preferencesName = preferences, directory = directory)
            manager.check(force = true); manager.download()
            withTimeout(15_000) { manager.state.first { it.phase == UpdatePhase.ERROR } }
            assertTrue(manager.state.value.message.orEmpty().contains("checksum"))
            assertFalse(File(directory, "update.apk").exists())
            assertFalse(File(directory, "download.part").exists())
        } finally { scope.cancel(); directory.deleteRecursively(); app.deleteSharedPreferences(preferences) }
    }
}
